def min_path_sum_brute(grid, i, j):
    m, n = len(grid), len(grid[0])
    if i == m - 1 and j == n - 1:
        return grid[i][j]
    if i == m - 1:
        return grid[i][j] + min_path_sum_brute(grid, i, j + 1)      # only right possible
    if j == n - 1:
        return grid[i][j] + min_path_sum_brute(grid, i + 1, j)      # only down possible
    return grid[i][j] + min(min_path_sum_brute(grid, i + 1, j), min_path_sum_brute(grid, i, j + 1))

