def min_path_sum(grid):
    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                dp[i][j] = grid[i][j]
            elif i == 0:
                dp[i][j] = dp[i][j - 1] + grid[i][j]                # first row: running total
            elif j == 0:
                dp[i][j] = dp[i - 1][j] + grid[i][j]                # first column: running total
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]  # cheaper of top or left
    return dp[m - 1][n - 1]

