int minPathSum(vector<vector<int>>& grid) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<int>> dp(m, vector<int>(n, 0));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (i == 0 && j == 0) dp[i][j] = grid[i][j];
            else if (i == 0) dp[i][j] = dp[i][j - 1] + grid[i][j];              // first row
            else if (j == 0) dp[i][j] = dp[i - 1][j] + grid[i][j];              // first column
            else dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j];         // cheaper neighbor
        }
    }
    return dp[m - 1][n - 1];
}
